object QuoteData {
    val quotes = listOf(
        // ── WISDOM (dayOfYear 1–40) ──────────────────────────────────────────
        QuoteEntity("q001", "Things cannot touch the mind. They stay outside, unmoved. Our distress comes only from our own opinion.", "marcus_aurelius", "Meditations", "WISDOM", 1),
        QuoteEntity("q002", "A reasoning mind can turn every obstacle into material for its own purpose.", "marcus_aurelius", "Meditations", "WISDOM", 2),
        QuoteEntity("q003", "Don't live as if you had ten thousand years. Death is near. While you live, while you can, be good.", "marcus_aurelius", "Meditations", "WISDOM", 3),
        QuoteEntity("q004", "Very little is needed to live a happy life.", "marcus_aurelius", "Meditations", "WISDOM", 4),
        QuoteEntity("q005", "Nothing lifts the mind like looking at everything in your life clearly and truly.", "marcus_aurelius", "Meditations", "WISDOM", 5),
        QuoteEntity("q006", "Above all, don't be disturbed. Everything follows nature, and soon you will be nobody and nowhere, like Hadrian and Augustus.", "marcus_aurelius", "Meditations", "WISDOM", 6),
        QuoteEntity("q007", "Love only what happens to you, what is woven into your life. What could suit you better?", "marcus_aurelius", "Meditations", "WISDOM", 7),
