        QuoteEntity("q014", "No one can learn what they think they already know.", "epictetus", "Discourses", "WISDOM", 14),
        QuoteEntity("q015", "People are upset not by what happens, but by their opinions about it.", "epictetus", "Enchiridion", "WISDOM", 15),
        QuoteEntity("q016", "Enjoy what you have now, and be content with what comes in its season.", "epictetus", "Discourses", "WISDOM", 16),
        QuoteEntity("q017", "If you want to be free, don't want or fear anything that depends on others. Otherwise you will be a slave.", "epictetus", "Enchiridion", "WISDOM", 17),
