        QuoteEntity("q020", "You can't spend time with someone covered in soot without getting some on yourself.", "epictetus", "Discourses", "WISDOM", 20),
        QuoteEntity("q021", "Why won't anyone admit their faults? Because they are still in them. Only someone awake can tell their dream.", "seneca", "Letters to Lucilius", "WISDOM", 21),
        QuoteEntity("q022", "We are wrong to see death as ahead of us. Most of it is already behind us.", "seneca", "Letters to Lucilius", "WISDOM", 22),
        QuoteEntity("q023", "A life is long if it is full.", "seneca", "Letters to Lucilius", "WISDOM", 23),
        QuoteEntity("q024", "We torment ourselves over what is coming and over what is past.", "seneca", "Letters to Lucilius", "WISDOM", 24),
