        QuoteEntity("q039", "It is not what others do that disturbs us; that comes from their own minds. It is our own opinions that disturb us.", "marcus_aurelius", "Meditations", "WISDOM", 39),
        QuoteEntity("q040", "A mind free of passion is a fortress. There is no safer refuge, and no one can take it.", "marcus_aurelius", "Meditations", "WISDOM", 40),

        // ── COURAGE (dayOfYear 41–80) ────────────────────────────────────────
        QuoteEntity("q041", "You could leave life at any moment. Let that shape everything you do and think.", "marcus_aurelius", "Meditations", "COURAGE", 41),
        QuoteEntity("q042", "Good character means living each day as your last: not frantic, not numb, not pretending.", "marcus_aurelius", "Meditations", "COURAGE", 42),
        QuoteEntity("q043", "Living is more like wrestling than dancing. You must stand ready and firm for sudden blows.", "marcus_aurelius", "Meditations", "COURAGE", 43),
        QuoteEntity("q044", "What is death? A scary mask. Turn it around and look. See, it doesn't bite.", "epictetus", "Discourses", "COURAGE", 44),
        QuoteEntity("q045", "Hard times show who people are.", "epictetus", "Discourses", "COURAGE", 45),
        QuoteEntity("q046", "No one is brave and earnest who avoids danger, or whose spirit doesn't grow as the task gets harder.", "seneca", "Letters to Lucilius", "COURAGE", 46),
        QuoteEntity("q047", "Life is really a battle.", "seneca", "Letters to Lucilius", "COURAGE", 47),
        QuoteEntity("q048", "Bravery is not recklessness or a love of danger. It is knowing what is truly bad and what is not.", "seneca", "Letters to Lucilius", "COURAGE", 48),
        QuoteEntity("q049", "No fighter goes into the ring with confidence who has never been beaten black and blue.", "seneca", "Letters to Lucilius", "COURAGE", 49),
        QuoteEntity("q050", "What is freedom? Not being a slave to any circumstance or chance, and meeting Fortune as an equal.", "seneca", "Letters to Lucilius", "COURAGE", 50),
        QuoteEntity("q051", "When a thought hurts, you can't stop it from arriving. But you can reason with it and keep it from growing.", "epictetus", "Discourses", "COURAGE", 51),
        QuoteEntity("q052", "What should you say when something painful happens? This is what I trained for.", "epictetus", "Discourses", "COURAGE", 52),
        QuoteEntity("q053", "Practice on small things first, then move on to greater ones.", "epictetus", "Discourses", "COURAGE", 53),
        QuoteEntity("q054", "Nothing happens to anyone that they are not made to bear.", "marcus_aurelius", "Meditations", "COURAGE", 54),
        QuoteEntity("q055", "Your habitual thoughts shape your character. The mind is dyed by its thoughts.", "marcus_aurelius", "Meditations", "COURAGE", 55),
        QuoteEntity("q056", "Do what is needed now. Get moving if you can, and don't look around to see who's watching.", "marcus_aurelius", "Meditations", "COURAGE", 56),
        QuoteEntity("q057", "Don't be swayed by people's blame or talk. If something is good to do or say, it is worthy of you.", "marcus_aurelius", "Meditations", "COURAGE", 57),
        QuoteEntity("q058", "No one can live in peace who worries too much about living longer.", "seneca", "Letters to Lucilius", "COURAGE", 58),
        QuoteEntity("q059", "Bravery is not proved only on the battlefield. You can be brave even lying in bed.", "seneca", "Letters to Lucilius", "COURAGE", 59),
        QuoteEntity("q060", "If you want to improve, be willing to look foolish about outside things. If others think you important, distrust yourself.", "epictetus", "Enchiridion", "COURAGE", 60),
        QuoteEntity("q061", "Retreat into yourself. The mind is content when it does what is right, and that brings calm.", "marcus_aurelius", "Meditations", "COURAGE", 61),
        QuoteEntity("q062", "If you don't know what the world is, you don't know where you are.", "marcus_aurelius", "Meditations", "COURAGE", 62),
        QuoteEntity("q063", "Your job is to play well the part you are given. Choosing the part is someone else's.", "epictetus", "Enchiridion", "COURAGE", 63),
        QuoteEntity("q064", "Steady your character, find your courage, and stand firm against what once frightened you.", "seneca", "Letters to Lucilius", "COURAGE", 64),
        QuoteEntity("q065", "Bravery is a fortress for our weakness. Inside it, you can wait out life's siege without fear, using your own strength.", "seneca", "Letters to Lucilius", "COURAGE", 65),
        QuoteEntity("q066", "If you don't want someone to flinch in a crisis, train them before it comes.", "seneca", "Letters to Lucilius", "COURAGE", 66),
        QuoteEntity("q067", "Work is food for noble minds.", "seneca", "Letters to Lucilius", "COURAGE", 67),
        QuoteEntity("q068", "Whatever outside thing you value, that value puts you in someone else's power.", "epictetus", "Discourses", "COURAGE", 68),
        QuoteEntity("q069", "The dice don't matter, and I can't know how they'll fall. Playing the roll carefully and well is my business.", "epictetus", "Discourses", "COURAGE", 69),
        QuoteEntity("q070", "You don't want a title. You want to be free, and the only way is to stop caring about what is not in your control.", "epictetus", "Enchiridion", "COURAGE", 70),
        QuoteEntity("q071", "No one ever saw Cato change, however much the state changed. He stayed the same in every situation.", "seneca", "Letters to Lucilius", "COURAGE", 71),
        QuoteEntity("q072", "Cato will take defeat in war as calmly as he took defeat in an election.", "seneca", "Letters to Lucilius", "COURAGE", 72),
