        QuoteEntity("q074", "Haven't you been given what you need to bear whatever happens? Greatness of spirit, courage, endurance?", "epictetus", "Discourses", "COURAGE", 74),
        QuoteEntity("q075", "Nothing outside can disturb or block a mind that is free by nature. Only your own opinions disturb you.", "epictetus", "Discourses", "COURAGE", 75),
        QuoteEntity("q076", "I turn to myself and ask if I make the same mistakes. How can I stop?", "epictetus", "Discourses", "COURAGE", 76),
        QuoteEntity("q077", "If you love a clay pot, remember it is a clay pot. Then if it breaks, you won't be upset.", "epictetus", "Enchiridion", "COURAGE", 77),
