        QuoteEntity("q079", "The only safe harbor in life's storms is to stop fearing the future, stand firm, and take whatever Fortune throws without running.", "seneca", "Letters to Lucilius", "COURAGE", 79),
        QuoteEntity("q080", "Have I done something for the common good? Then I have my reward. Keep this in mind, and never stop.", "marcus_aurelius", "Meditations", "COURAGE", 80),

        // ── JUSTICE (dayOfYear 81–120) ───────────────────────────────────────
        QuoteEntity("q081", "One thing is worth a great deal: to live with truth and justice, and kindness even toward liars and cheats.", "marcus_aurelius", "Meditations", "JUSTICE", 81),
        QuoteEntity("q082", "Each morning, tell yourself: today I will meet busybodies and people who are ungrateful, arrogant, dishonest, jealous, and unfriendly. They are this way because they don't know good from bad.", "marcus_aurelius", "Meditations", "JUSTICE", 82),
        QuoteEntity("q083", "What is not good for the swarm is not good for the bee.", "marcus_aurelius", "Meditations", "JUSTICE", 83),
        QuoteEntity("q084", "My nature is rational and social. As emperor, my city is Rome. As a human being, it is the world.", "marcus_aurelius", "Meditations", "JUSTICE", 84),
        QuoteEntity("q085", "We are made to work together, like hands, feet, eyelids, and teeth. Working against each other goes against nature.", "marcus_aurelius", "Meditations", "JUSTICE", 85),
        QuoteEntity("q086", "You often do wrong by failing to act, not only by acting.", "marcus_aurelius", "Meditations", "JUSTICE", 86),
        QuoteEntity("q087", "Whoever does wrong, wrongs themselves. To act unjustly is to make yourself bad.", "marcus_aurelius", "Meditations", "JUSTICE", 87),
